import Foundation

/// Google Fonts' category, stroke, and tags for each atlas family, generated by
/// `script/spine-font-tags.py` from the google/fonts repository's human-assessed tags
/// (`tags/all/families.csv`), whose license is unconfirmed (google/fonts issue #9347).
///
/// Tags score 0 to 100 and name a classification ("Serif/Didone"), a theme ("Theme/Art Deco"),
/// or a mood ("Expressive/Playful"). `BookAnalyzer.families(for:)` sorts families into the
/// reading's pools by them.
struct SpineFontTags: Sendable {
    struct Family: Decodable, Sendable {
        let category: String
        let stroke: String?
        let tags: [String: Int]
    }

    /// A family's coarse letterform class.
    enum Group: Sendable {
        case serif, slab, sans, script, monospace, display
    }

    /// A family's one identity, which decides the only pools it can join, so a face Google tags
    /// several ways, such as a Techno sans or a blackletter script, never joins a plain pool.
    enum Identity: Hashable, Sendable {
        case serif, slab, sans, script, monospace, blackletter, display
        /// A face whose strongest theme, such as "Pixel", sets its look.
        case themed(String)
    }

    let families: [String: Family]

    static let shared: SpineFontTags? = Bundle.main
        .url(forResource: "SpineFontTags", withExtension: "json")
        .flatMap { try? Data(contentsOf: $0) }
        .flatMap { try? JSONDecoder().decode(File.self, from: $0) }
        .map { SpineFontTags(families: $0.families) }

    private struct File: Decodable {
        let families: [String: Family]
    }

    /// `family`'s score for `tag`, 0 when untagged.
    func score(_ family: String, _ tag: String) -> Int {
        families[family]?.tags[tag] ?? 0
    }

    /// `family`'s highest score among `tags`.
    func score(_ family: String, anyOf tags: [String]) -> Int {
        tags.map { score(family, $0) }.max() ?? 0
    }

    /// `family`'s class: handwriting by Google's category, monospace by its category or tag, else
    /// the strongest classification tag of 50 or more, else the stroke Google records, so a face
    /// such as Italiana, which Google tags Serif/Modern but whose stroke it records as sans, is a
    /// serif. A family without any is display.
    func group(of family: String) -> Group? {
        guard let entry = families[family] else { return nil }
        if entry.category == "Handwriting" { return .script }
        // Google records some monospace families, such as Noto Sans Mono, as sans without the tag.
        if entry.category == "Monospace" || (entry.tags["Monospace/Monospace"] ?? 0) >= 50
            || family.hasSuffix(" Mono")
        {
            return .monospace
        }
        let classes: [(Group, String)] = [
            (.serif, "Serif/"), (.slab, "Slab/"), (.sans, "Sans/"), (.script, "Script/"),
            (.monospace, "Monospace/"),
        ]
        let strongest =
            classes.map { group, prefix in
                (group, entry.tags.filter { $0.key.hasPrefix(prefix) }.values.max() ?? 0)
            }
            .max { $0.1 < $1.1 }
        if let strongest, strongest.1 >= 50 { return strongest.0 }
        switch entry.stroke ?? entry.category {
        case "Serif": return .serif
        case "Slab Serif": return .slab
        case "Sans Serif": return .sans
        default: return .display
        }
    }

    /// `family`'s identity, from the first rule that matches:
    /// 1. Blackletter: tagged blackletter at 50 or more without a serif, sans, or slab class,
    ///    which keeps out mistagged faces such as Bodoni Moda.
    /// 2. Themed: its strongest other theme at 50 or more, ties going to the first by name.
    ///    Brush doesn't count for a handwriting face, since brush lettering is handwriting.
    /// 3. Monospace, by `group(of:)`.
    /// 4. Script: Google files it as handwriting.
    /// 5. Display: Google files it as display, or its category and classes at 50 or more mix
    ///    serif or slab, sans, and script, such as Italiana or Artifika.
    /// 6. Its class, by `group(of:)`.
    func identity(of family: String) -> Identity? {
        guard let entry = families[family], let group = group(of: family) else { return nil }
        func hasClass(_ prefixes: [String]) -> Bool {
            entry.tags.contains { tag, score in
                score >= 50 && prefixes.contains(where: tag.hasPrefix)
            }
        }
        if score(family, "Theme/Blackletter") >= 50 && !hasClass(["Serif/", "Sans/", "Slab/"]) {
            return .blackletter
        }
        let themes = entry.tags.filter { tag, score in
            score >= 50 && tag.hasPrefix("Theme/") && tag != "Theme/Blackletter"
                && !(entry.category == "Handwriting" && tag == "Theme/Brush")
        }
        if let theme = themes.max(by: { ($0.value, $1.key) < ($1.value, $0.key) }) {
            return .themed(String(theme.key.dropFirst("Theme/".count)))
        }
        if group == .monospace { return .monospace }
        if entry.category == "Handwriting" { return .script }
        let kinds = [["Serif/", "Slab/"], ["Sans/"], ["Script/"]]
        let filed = ["Serif": kinds[0], "Sans Serif": kinds[1]][entry.category]
        let mixed = kinds.filter { $0 == filed || hasClass($0) }.count > 1
        if entry.category == "Display" || mixed { return .display }
        return switch group {
        case .serif: .serif
        case .slab: .slab
        case .sans: .sans
        case .script: .script
        case .monospace: .monospace
        case .display: .display
        }
    }
}
